 if (typeof raw !== 'string') return null
 let text = raw.trim()
 const fenced = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/)
 if (fenced) text = fenced[1]
 try {
  const r = JSON.parse(text)
  if (!['PASS','REVISE'].includes(r.vote) || typeof r.coverage_complete !== 'boolean' || !Array.isArray(r.findings) || !Array.isArray(r.pending) || !Array.isArray(r.prior_findings)) return null
