const results = Array(ROLES.length).fill(null)
let next = 0, roundExpired = false
let finishRound
const roundDeadline = new Promise(resolve => { finishRound = resolve })
const roundTimer = setTimeout(() => { roundExpired = true; log('整轮300s截止；未完成与排队项不得计PASS。'); finishRound('round_timeout') }, 300000)
function parse(raw) {
 if (typeof raw !== 'string') return null
 let text = raw.trim()
 const fenced = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/)
 if (fenced) text = fenced[1]
 try {
  const r = JSON.parse(text)
  if (!['PASS','REVISE'].includes(r.vote) || typeof r.coverage_complete !== 'boolean' || !Array.isArray(r.findings) || !Array.isArray(r.pending) || !Array.isArray(r.prior_findings)) return null
  for (const f of r.findings) if (!['critical','major','minor'].includes(f.severity) || !['issue','risk','decision'].includes(f.type) || !['implementation','testing','documentation','architecture'].includes(f.category) || typeof f.scope !== 'string' || typeof f.file !== 'string' || !Number.isInteger(f.line) || f.line < 1 || typeof f.failure_scenario !== 'string') return null
  if ((!r.coverage_complete || r.pending.length || r.findings.some(f => ['critical','major'].includes(f.severity))) && r.vote !== 'REVISE') return null
  return r
 } catch { return null }
}

async function worker() {
 while (!roundExpired && next < ROLES.length) {
  const index = next++, role = ROLES[index]
  let seatExpired = false
  const seatTimer = setTimeout(() => { seatExpired = true; log(role.name + ':120s超时，票不准入；请求未结束前不释放本worker活跃槽。') },120000)

  const opts = {agentType:'aria:'+role.name,label:'R4:'+role.name,phase:'Formal R4'}
  if (role.model) opts.model = role.model
  let raw = null, error = null
  try { raw = await agent(prompt,opts) } catch (e) { error = String(e).slice(0,200) }
  clearTimeout(seatTimer)
  const report = !seatExpired && !roundExpired ? parse(raw) : null
  results[index] = {role:role.name,configuredModel:role.model || 'inherit',status:seatExpired || roundExpired ? 'timeout' : report ? 'completed' : 'error',report,rawUnadmitted:report ? null : raw,error}
  log(role.name+':'+results[index].status+(report ? ' vote='+report.vote : ''))
 }
}
const all = Promise.all([worker(),worker()]).then(()=>'collected')
const terminal = await Promise.race([all,roundDeadline])
clearTimeout(roundTimer)
for (let i=0;i<results.length;i++) if (!results[i]) results[i]={role:ROLES[i].name,configuredModel:ROLES[i].model || 'inherit',status:roundExpired ? 'round_timeout_or_not_started' : 'missing',report:null}
const admitted = results.filter(r=>r.status==='completed')
return {round:4,candidate:'49d7da44941ae41a9b4e5a7321d114f14e3ec3a5',terminal,roundExpired,maxParallel:2,singleAgentSeconds:120,roundSeconds:300,configuredRoles:7,admittedCount:admitted.length,incomplete:admitted.length!==7,allFailedVoid:admitted.length===0,unanimousPass:admitted.length>0 && admitted.every(r=>r.report.vote==='PASS'),results,mergeClearance:false,note:'宿主定时器判准入；不声称逐席原生请求在120s被硬杀，未结束前保持活跃槽。仅本轮结果，不自动宣称稳定或合并。'}

